+                        results.Add($"[{link.GetString()}] {text.GetString()}");
+                    }
+                }
+            }
+
+            if (results.Count > 0)
+                return string.Join("\n\n", results);
+
+            // Fallback: DuckDuckGo HTML search
+            return await HtmlFallbackSearchAsync(encoded);
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed: {ex.Message}";
+        }
+    }
+
+    private static async Task<string> HtmlFallbackSearchAsync(string encodedQuery)
+    {
+        try
+        {
+            var url = $"https://html.duckduckgo.com/html/?q={encodedQuery}";
+            var html = await s_http.GetStringAsync(url);
+
+            var results = new List<string>();
+            var snippetTag = "class=\"result__snippet\"";
+            var linkTag = "class=\"result__url\"";
+            var idx = 0;
+            for (var i = 0; i < 5; i++)
+            {
+                idx = html.IndexOf(snippetTag, idx, StringComparison.Ordinal);
+                if (idx < 0) break;
+                var start = html.IndexOf('>', idx) + 1;
+                var end = html.IndexOf('<', start);
+                if (start > 0 && end > start)
+                {
+                    var snippet = System.Net.WebUtility.HtmlDecode(
+                        html[start..end].Trim());
+                    if (!string.IsNullOrWhiteSpace(snippet))
+                        results.Add(snippet);
+                }
+                idx = end;
+            }
+
+            return results.Count > 0
+                ? string.Join("\n\n", results)
+                : "No results found.";
+        }
+        catch
+        {
+            return "No results found.";
+        }
+    }
+}
+
+// ── Research Notebook ───────────────────────────────────────────────────────
+class ResearchNotebook
+{
+    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];
+
+    public void Add(string title, string content)
+        => _notes.Add((title, content, DateTime.UtcNow));
+
+    public string GetAll()
+    {
+        if (_notes.Count == 0) return "No notes saved yet.";
+        return string.Join("\n\n---\n\n",
+            _notes.Select((n, i) => $"Note {i + 1}: {n.Title}\n{n.Content}"));
+    }
+
+    public void Clear() => _notes.Clear();
+}

