111. static class WebSearchTool
112. {
113.     private static readonly HttpClient s_http = new()
114.     {
115.         DefaultRequestHeaders =
116.         {
117.             { "User-Agent", "ResearchAgent/1.0" },
118.             { "Accept", "application/json" },
119.         },
120.         Timeout = TimeSpan.FromSeconds(15),
121.     };
122. 
123.     /// <summary>
124.     /// Searches the web using the DuckDuckGo Instant Answer API (no key required).
125.     /// Falls back to a lite HTML scrape if the API returns no abstract.
126.     /// </summary>
127.     public static async Task<string> SearchAsync(string query)
128.     {
129.         try
130.         {
131.             var encoded = Uri.EscapeDataString(query);
132. 
133.             // DuckDuckGo Instant Answer API
134.             var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_redirect=1";
135.             var json = await s_http.GetStringAsync(url);
136.             using var doc = JsonDocument.Parse(json);
137.             var root = doc.RootElement;
138. 
139.             var results = new List<string>();
140. 
141.             var abstractText = root.GetProperty("Abstract").GetString();
142.             var abstractUrl = root.GetProperty("AbstractURL").GetString();
143.             if (!string.IsNullOrWhiteSpace(abstractText))
144.                 results.Add($"[{abstractUrl}] {abstractText}");
145. 
146.             if (root.TryGetProperty("RelatedTopics", out var topics))
147.             {
148.                 foreach (var topic in topics.EnumerateArray().Take(5))
149.                 {
150.                     if (topic.TryGetProperty("Text", out var text) &&
151.                         topic.TryGetProperty("FirstURL", out var link))
152.                     {
153.                         results.Add($"[{link.GetString()}] {text.GetString()}");
154.                     }
155.                 }
156.             }
157. 
158.             if (results.Count > 0)
159.                 return string.Join("\n\n", results);
160. 
161.             // Fallback: DuckDuckGo HTML search
162.             return await HtmlFallbackSearchAsync(encoded);
163.         }
164.         catch (Exception ex)
165.         {
166.             return $"Search failed: {ex.Message}";
167.         }
168.     }
