171.     {
172.         try
173.         {
174.             var url = $"https://html.duckduckgo.com/html/?q={encodedQuery}";
175.             var html = await s_http.GetStringAsync(url);
176. 
177.             var results = new List<string>();
178.             var snippetTag = "class=\"result__snippet\"";
179. 
180.             var idx = 0;
181.             for (var i = 0; i < 5; i++)
182.             {
183.                 idx = html.IndexOf(snippetTag, idx, StringComparison.Ordinal);
184.                 if (idx < 0) break;
185.                 var start = html.IndexOf('>', idx) + 1;
186.                 var end = html.IndexOf('<', start);
187.                 if (start > 0 && end > start)
188.                 {
189.                     var snippet = System.Net.WebUtility.HtmlDecode(
190.                         html[start..end].Trim());
191.                     if (!string.IsNullOrWhiteSpace(snippet))
192.                         results.Add(snippet);
193.                 }
194.                 idx = end;
195.             }
196. 
197.             return results.Count > 0
198.                 ? string.Join("\n\n", results)
199.                 : "No results found.";
200.         }
201.         catch
202.         {
203.             return "No results found.";
204.         }
205.     }
