 using System.ComponentModel;
 using System.Text.Json;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;
 using OpenAI;

 // ── Configuration ───────────────────────────────────────────────────────────
 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

 // ── Chat client ─────────────────────────────────────────────────────────────
 var openAiClient = new OpenAIClient(apiKey);
 IChatClient chatClient = openAiClient.GetChatClient(modelId).AsIChatClient();

 // ── Tools ───────────────────────────────────────────────────────────────────
 var notebook = new ResearchNotebook();

 var tools = new AITool[]
 {
     AIFunctionFactory.Create(
         ([Description("The search query")] string query) =>
         {
             Console.WriteLine($"  🔍 Searching: \"{query}\"");
             return WebSearchTool.SearchAsync(query);
         },
         "web_search",
         "Search the web for information on a topic. Returns a list of result snippets."),
     AIFunctionFactory.Create(
         ([Description("Short title for the note")] string title,
          [Description("The content to save")] string content) =>
         {
             Console.WriteLine($"  📝 Saving note: \"{title}\"");
             notebook.Add(title, content);
             return $"Note saved: {title}";
         },
         "save_note",
         "Save a research note with a title and content for later summarization."),
     AIFunctionFactory.Create(
         () =>
         {
             Console.WriteLine("  📋 Reading all notes");
             return notebook.GetAll();
         },
         "get_notes",
         "Retrieve all saved research notes."),
 };

 // ── Agent ───────────────────────────────────────────────────────────────────
 var agent = new ChatClientAgent(
     chatClient,
     instructions: """
         You are a research agent. When the user gives you a topic:
         1. Use web_search to find information (make 2-3 searches with varied queries).
         2. Use save_note to record key findings from each search.
         3. Use get_notes to review everything you have collected.
         4. Provide a concise, well-structured summary of your findings with key points.
         Always cite the sources (URLs) you found.
         """,
     name: "ResearchAgent",
     description: "An agent that researches topics using web search and note-taking.",
     tools: tools);

 // ── Run ─────────────────────────────────────────────────────────────────────
 Console.WriteLine("╔══════════════════════════════════════════╗");
 Console.WriteLine("║       Research Agent (type 'exit')       ║");
 Console.WriteLine("╚══════════════════════════════════════════╝");
 Console.WriteLine();

 var runOptions = new ChatClientAgentRunOptions(new ChatOptions
 {
     Temperature = 0f,
     MaxOutputTokens = 2048,
 });

 while (true)
 {
     Console.Write("Topic> ");
     var topic = Console.ReadLine();
     if (string.IsNullOrWhiteSpace(topic) || topic.Equals("exit", StringComparison.OrdinalIgnoreCase))
         break;

     Console.WriteLine();
     try
     {
         var session = await agent.CreateSessionAsync();
         var response = await agent.RunAsync(
             $"Research the following topic and provide a summary: {topic}",
             session,
             runOptions);

         Console.WriteLine();
         Console.WriteLine("═══ Research Summary ═══");
         Console.WriteLine(response.Text);
         Console.WriteLine("════════════════════════");
     }
     catch (Exception ex)
     {
         Console.WriteLine($"Error: {ex.Message}");
     }

     notebook.Clear();
     Console.WriteLine();
 }

 Console.WriteLine("Goodbye!");

 // ── Web Search Tool ─────────────────────────────────────────────────────────
 static class WebSearchTool
 {
     private static readonly HttpClient s_http = new()
     {
         DefaultRequestHeaders =
         {
             { "User-Agent", "ResearchAgent/1.0" },
             { "Accept", "application/json" },
         },
         Timeout = TimeSpan.FromSeconds(15),
     };

     /// <summary>
     /// Searches the web using the DuckDuckGo Instant Answer API (no key required).
     /// Falls back to a lite HTML scrape if the API returns no abstract.
     /// </summary>
     public static async Task<string> SearchAsync(string query)
     {
         try
         {
             var encoded = Uri.EscapeDataString(query);

             // DuckDuckGo Instant Answer API
             var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_redirect=1";
             var json = await s_http.GetStringAsync(url);
             using var doc = JsonDocument.Parse(json);
             var root = doc.RootElement;

             var results = new List<string>();

             var abstractText = root.GetProperty("Abstract").GetString();
             var abstractUrl = root.GetProperty("AbstractURL").GetString();
             if (!string.IsNullOrWhiteSpace(abstractText))
                 results.Add($"[{abstractUrl}] {abstractText}");

             if (root.TryGetProperty("RelatedTopics", out var topics))
             {
                 foreach (var topic in topics.EnumerateArray().Take(5))
                 {
                     if (topic.TryGetProperty("Text", out var text) &&
                         topic.TryGetProperty("FirstURL", out var link))
                     {
                         results.Add($"[{link.GetString()}] {text.GetString()}");
                     }
                 }
             }

             if (results.Count > 0)
                 return string.Join("\n\n", results);

             // Fallback: DuckDuckGo HTML search
             return await HtmlFallbackSearchAsync(encoded);
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}";
         }
     }

     private static async Task<string> HtmlFallbackSearchAsync(string encodedQuery)
     {
         try
         {
             var url = $"https://html.duckduckgo.com/html/?q={encodedQuery}";
             var html = await s_http.GetStringAsync(url);

             var results = new List<string>();
             var snippetTag = "class=\"result__snippet\"";

             var idx = 0;
             for (var i = 0; i < 5; i++)
             {
                 idx = html.IndexOf(snippetTag, idx, StringComparison.Ordinal);
                 if (idx < 0) break;
                 var start = html.IndexOf('>', idx) + 1;
                 var end = html.IndexOf('<', start);
                 if (start > 0 && end > start)
                 {
                     var snippet = System.Net.WebUtility.HtmlDecode(
                         html[start..end].Trim());
                     if (!string.IsNullOrWhiteSpace(snippet))
                         results.Add(snippet);
                 }
                 idx = end;
             }

             return results.Count > 0
                 ? string.Join("\n\n", results)
                 : "No results found.";
         }
         catch
         {
             return "No results found.";
         }
     }
 }

 // ── Research Notebook ───────────────────────────────────────────────────────
 class ResearchNotebook
 {
     private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

     public void Add(string title, string content)
         => _notes.Add((title, content, DateTime.UtcNow));

     public string GetAll()
     {
         if (_notes.Count == 0) return "No notes saved yet.";
         return string.Join("\n\n---\n\n",
             _notes.Select((n, i) => $"Note {i + 1}: {n.Title}\n{n.Content}"));
     }

     public void Clear() => _notes.Clear();
 }
